CREATE OR REPLACE FUNCTION private.attendance_refresh_payroll()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if tg_op<>'INSERT' then perform private.refresh_automatic_payroll(old.company_id,old.worker_id,old.work_date); end if;
 if tg_op<>'DELETE' then perform private.refresh_automatic_payroll(new.company_id,new.worker_id,new.work_date); end if;
 return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.decide_paid_leave_request(p_batch_id uuid, p_decision text, p_note text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_company_id uuid;
  v_requested_by uuid;
  v_worker_id uuid;
  v_status text;
  v_granted numeric := 0;
  v_used numeric := 0;
  v_batch_count numeric := 0;
begin
  if p_decision not in ('approve','reject') then
    raise exception 'invalid decision';
  end if;

  select r.company_id, r.requested_by, r.worker_id
  into v_company_id, v_requested_by, v_worker_id
  from public.paid_leave_requests r
  where r.batch_id = p_batch_id
    and r.status = 'pending'
  limit 1
  for update;

  if v_company_id is null then
    raise exception 'pending paid leave request not found';
  end if;

  if not exists (
    select 1
    from public.company_members cm
    where cm.company_id = v_company_id
      and cm.user_id = v_actor
      and cm.role::text in ('owner','admin','manager')
  ) then
    raise exception 'management permission required';
  end if;

  if p_decision = 'approve' then
    select coalesce(wps.paid_leave_granted_days, 0)
    into v_granted
    from public.worker_payroll_settings wps
    where wps.worker_id = v_worker_id
    limit 1;
    v_granted := coalesce(v_granted, 0);

    select count(*)
    into v_used
    from public.paid_leave_requests r
    where r.worker_id = v_worker_id
      and r.status = 'approved';

    select count(*)
    into v_batch_count
    from public.paid_leave_requests r
    where r.batch_id = p_batch_id
      and r.status = 'pending';

    if v_used + v_batch_count > v_granted then
      raise exception 'paid leave balance exceeded';
    end if;

    v_status := 'approved';
  else
    v_status := 'rejected';
  end if;

  update public.paid_leave_requests
  set status = v_status,
      reviewed_by = v_actor,
      reviewed_at = now(),
      review_note = nullif(trim(coalesce(p_note,'')), ''),
      updated_at = now()
  where batch_id = p_batch_id
    and status = 'pending';

  perform private.enqueue_notification(
    v_company_id,
    v_requested_by,
    case when v_status = 'approved' then 'approval' else 'warning' end,
    case when v_status = 'approved'
      then '有給申請が承認されました'
      else '有給申請が却下されました'
    end,
    case when v_status = 'approved'
      then '申請した有給が承認されました。出勤表に反映されます。'
      else '有給申請が却下されました。内容を確認してください。'
    end,
    'paid_leave_request',
    p_batch_id
  );

  return v_status;
end;
$function$

CREATE OR REPLACE FUNCTION private.attendance_sync_payroll_detail()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_op <> 'INSERT' then
    perform private.sync_payroll_attendance_detail(old.company_id,old.worker_id,old.work_date);
  end if;
  if tg_op <> 'DELETE' then
    perform private.sync_payroll_attendance_detail(new.company_id,new.worker_id,new.work_date);
  end if;
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION private.paid_leave_sync_payroll_detail()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_op <> 'INSERT' then
    perform private.sync_payroll_attendance_detail(old.company_id,old.worker_id,old.leave_date);
  end if;
  if tg_op <> 'DELETE' then
    perform private.sync_payroll_attendance_detail(new.company_id,new.worker_id,new.leave_date);
  end if;
  return null;
end;
$function$
